# -*- coding: utf-8 -*-
"""Оболочка страниц (стили пар 1–2, скрипт лайтбокса/iframe/чек-листа/квиза). Скопировано из урока 3."""
EXTRA_CSS = "\n/* УРОК 3 */\n.details-key .body > .prompt-box + .prompt-box,.details-key .body > .prompt-box + p,.details-key .body > ol + .prompt-box{margin-top:14px}\ncode{font-family:Consolas,'Courier New',monospace;font-size:.86em;background:var(--indigo-lt);color:var(--indigo-dk);padding:1px 5px;border-radius:5px}\n.prompt-desc{padding:8px 16px 0;color:#94a3b8;font-size:.8rem}\ntable.board td:not(:first-child){text-align:center}\n.cell{min-width:64px;padding:6px 10px;border-radius:9px;border:1px solid var(--border);background:#fff;font:inherit;font-weight:900;font-size:1rem;cursor:pointer;color:var(--muted)}\n.cell.ok{background:var(--green-lt);border-color:#86efac;color:var(--green)}\n.cell.bad{background:var(--red-lt);border-color:#fca5a5;color:var(--red)}\n.formula .f span[style]{text-decoration:line-through dotted rgba(255,255,255,.5)}\n"
SCRIPT = '\n/* Префикс имени файла при скачивании слайдов */\nconst BRAND = "dpo1-urok4";\n\nconst reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;\nif (!reduceMotion && "IntersectionObserver" in window) {\n  const reveal = new IntersectionObserver((entries) => {\n    entries.forEach((entry) => {\n      if (entry.isIntersecting) { entry.target.classList.add("in"); reveal.unobserve(entry.target); }\n    });\n  }, {threshold: 0.06, rootMargin: "0px 0px -24px"});\n  document.querySelectorAll(".fade").forEach((element) => reveal.observe(element));\n} else {\n  document.querySelectorAll(".fade").forEach((element) => element.classList.add("in"));\n}\n\n/* Подсветка активной секции в навбаре */\nconst navLinks = [...document.querySelectorAll(".nav-link")];\nconst sections = [...document.querySelectorAll("main section[id]")];\nif ("IntersectionObserver" in window) {\n  const sectionObserver = new IntersectionObserver((entries) => {\n    entries.forEach((entry) => {\n      if (!entry.isIntersecting) return;\n      navLinks.forEach((link) => link.classList.toggle("active", link.getAttribute("href") === `#${entry.target.id}`));\n    });\n  }, {rootMargin: "-35% 0px -55%", threshold: 0});\n  sections.forEach((section) => sectionObserver.observe(section));\n}\n\n/* Лайтбокс */\nconst lightbox = document.getElementById("lightbox");\nconst lightboxImg = document.getElementById("lightbox-img");\nconst lightboxDownload = document.getElementById("lightbox-download");\ndocument.querySelectorAll(".img-card[data-lightbox]").forEach((card) => {\n  card.addEventListener("click", () => {\n    if (card.classList.contains("img-missing")) return;\n    const img = card.querySelector("img");\n    lightboxImg.src = img.src;\n    lightboxImg.alt = img.alt;\n    lightboxDownload.href = img.src;\n    lightboxDownload.download = `${BRAND}_${img.src.split("/").pop().split("?")[0]}`;\n    lightbox.classList.add("open");\n    lightbox.setAttribute("aria-hidden", "false");\n  });\n});\nfunction closeLightbox() {\n  if (lightbox.contains(document.activeElement)) document.activeElement.blur();\n  lightbox.classList.remove("open");\n  lightbox.setAttribute("aria-hidden", "true");\n  lightboxImg.src = "";\n}\ndocument.getElementById("lightbox-close").addEventListener("click", closeLightbox);\nlightbox.addEventListener("click", (event) => { if (event.target === lightbox) closeLightbox(); });\n\n/* Фуллскрин для iframe-карточек */\nconst fsOverlay = document.getElementById("fs-overlay");\nconst fsFrame = document.getElementById("fs-frame");\nconst fsTitle = document.getElementById("fs-title");\ndocument.querySelectorAll(".viz-fs").forEach((button) => {\n  button.addEventListener("click", () => {\n    fsFrame.src = button.dataset.fsSrc;\n    fsTitle.textContent = button.dataset.fsTitle;\n    fsOverlay.classList.add("open");\n    fsOverlay.setAttribute("aria-hidden", "false");\n  });\n});\nfunction closeFs() {\n  if (fsOverlay.contains(document.activeElement)) document.activeElement.blur();\n  fsOverlay.classList.remove("open");\n  fsOverlay.setAttribute("aria-hidden", "true");\n  fsFrame.src = "";\n}\ndocument.getElementById("fs-close").addEventListener("click", closeFs);\ndocument.addEventListener("keydown", (event) => {\n  if (event.key !== "Escape") return;\n  if (fsOverlay.classList.contains("open")) { closeFs(); } else { closeLightbox(); }\n});\n\n/* Высота демо под содержимое (паттерн 6): наблюдателя создаём в окне самого демо */\nconst narrowQuery = window.matchMedia("(max-width: 760px)");\ndocument.querySelectorAll(".viz iframe").forEach((frame) => {\n  const baseHeight = Number(frame.getAttribute("height")) || 560;\n  const autofit = frame.hasAttribute("data-autofit");\n  let observer = null;\n  const fit = () => {\n    try {\n      const body = frame.contentDocument && frame.contentDocument.body;\n      if (!body) return;\n      frame.style.height = narrowQuery.matches || autofit ? `${Math.max(Math.min(baseHeight, 420), Math.ceil(body.scrollHeight) + 4)}px` : "";\n    } catch { /* другой origin (file://) — остаётся фиксированная высота */ }\n  };\n  const watch = () => {\n    fit();\n    try {\n      if (observer) observer.disconnect();\n      const FrameObserver = (frame.contentWindow && frame.contentWindow.ResizeObserver) || ResizeObserver;\n      observer = new FrameObserver(fit);\n      if (autofit) {\n        const refit = () => { fit(); [400, 1500, 7000].forEach((ms) => window.setTimeout(fit, ms)); };\n        frame.contentDocument.addEventListener("click", refit, true);\n        frame.contentDocument.addEventListener("input", refit, true);\n      }\n      observer.observe(frame.contentDocument.body);\n    } catch { /* нет доступа к документу демо */ }\n  };\n  frame.addEventListener("load", watch);\n  const details = frame.closest("details");\n  if (details) details.addEventListener("toggle", () => { if (details.open) { fit(); window.setTimeout(fit, 300); } });\n  try {\n    const doc = frame.contentDocument;\n    if (doc && doc.readyState === "complete" && doc.URL !== "about:blank") watch();\n  } catch { /* нет доступа к документу демо */ }\n  if (narrowQuery.addEventListener) narrowQuery.addEventListener("change", fit);\n});\n\n/* Копирование промптов */\ndocument.querySelectorAll("[data-copy]").forEach((button) => {\n  button.addEventListener("click", async () => {\n    const code = document.getElementById(button.dataset.copy);\n    if (!code) return;\n    const original = button.textContent;\n    try { await navigator.clipboard.writeText(code.innerText); button.textContent = "Скопировано"; }\n    catch { button.textContent = "Выделите текст"; }\n    window.setTimeout(() => { button.textContent = original; }, 1600);\n  });\n});\n\n/* Голосование во входном блоке: кнопки только подсвечивают выбор, голосует зал в чате */\nconst POLL_TEXT = {\n  yes: "Позиция зафиксирована: «секретного нет». Откройте ключ ниже — в письме пять утечек.",\n  no: "Позиция зафиксирована: «есть лишнее». Сколько утечек вы насчитали? Ключ — ниже.",\n};\ndocument.querySelectorAll(".poll-opt").forEach((option) => {\n  option.addEventListener("click", () => {\n    const group = option.dataset.poll;\n    document.querySelectorAll(`.poll-opt[data-poll="${group}"]`).forEach((o) => o.classList.toggle("chosen", o === option));\n    const answer = document.getElementById(`poll-answer-${group}`);\n    if (answer) answer.textContent = POLL_TEXT[option.dataset.vote];\n  });\n});\n\n/* Табло сравнения моделей: ? → ✓ → ✗ */\ndocument.querySelectorAll("#board .cell").forEach((cell) => {\n  cell.addEventListener("click", () => {\n    const next = {"?": "✓", "✓": "✗", "✗": "?"}[cell.textContent] || "?";\n    cell.textContent = next;\n    cell.classList.toggle("ok", next === "✓");\n    cell.classList.toggle("bad", next === "✗");\n  });\n});\n\n/* Чек-лист */\nconst CHECKLIST_KEY = "dpo1-urok4-v2-checklist";\nconst checklistInputs = [...document.querySelectorAll("[data-checklist-item]")];\nconst checklistProgress = document.getElementById("checklist-progress");\nconst checklistDone = document.getElementById("checklist-done");\nfunction loadChecklistState() {\n  try { return JSON.parse(localStorage.getItem(CHECKLIST_KEY) || "{}"); } catch { return {}; }\n}\nfunction saveChecklistState(state) {\n  try { localStorage.setItem(CHECKLIST_KEY, JSON.stringify(state)); } catch { /* приватный режим */ }\n}\nfunction renderChecklistProgress() {\n  const checked = checklistInputs.filter((input) => input.checked).length;\n  checklistProgress.style.width = `${Math.round((checked / checklistInputs.length) * 100)}%`;\n  checklistDone.hidden = checked !== checklistInputs.length;\n}\nconst savedChecklist = loadChecklistState();\nchecklistInputs.forEach((input) => {\n  const key = input.dataset.checklistItem;\n  input.checked = Boolean(savedChecklist[key]);\n  input.addEventListener("change", () => {\n    const state = loadChecklistState();\n    state[key] = input.checked;\n    saveChecklistState(state);\n    renderChecklistProgress();\n  });\n});\nrenderChecklistProgress();\n\n/* Квиз */\nconst QUIZ_TOTAL = document.querySelectorAll(".quiz-question").length;\nconst QUIZ_EXPLAIN = {\n  1: "Важно, какая информация ушла, а не в каком виде. Пересказ характеристик — такая же передача, как загрузка паспорта изделия.",\n  2: "Юрисдикция и настройки снижают риски, но не меняют статус документа. Внутренний документ — только в инструмент, разрешённый организацией.",\n  3: "Чтобы обезличить, нейросеть должна получить оригинал. Обезличиваем у себя: «Найти и заменить», Инспектор документов, учебный обезличиватель.",\n  4: "Имя файла, автор и организация в свойствах, примечания рецензентов уходят вместе с файлом. Надёжнее вставлять текст.",\n  5: "Настройка обучения не удаляет данные: они хранятся на серверах сервиса. Рабочие документы это не разрешает.",\n  6: "Каждая новость открыта, но сводная карта поставщиков и сроков — новые сведения. Сомневаетесь — красный.",\n  7: "Пункт 5.1 условий «Алисы AI» от 10.09.2026: «исключительно для некоммерческого использования… для развлекательных целей».",\n  8: "Роль задаёт позицию, критерии и тон. В исследовании на 162 ролях точность ответов не выросла; права на данные роль не даёт.",\n};\nlet quizAnswered = 0;\nconst quizScoreEl = document.getElementById("quiz-score");\ndocument.querySelectorAll(".quiz-check").forEach((button) => {\n  button.addEventListener("click", () => {\n    const index = button.dataset.quizCheck;\n    const question = document.querySelector(`.quiz-question[data-quiz="${index}"]`);\n    const selected = question.querySelector(`input[name="q${index}"]:checked`);\n    const feedback = document.querySelector(`[data-quiz-feedback="${index}"]`);\n    if (!selected) {\n      feedback.textContent = "Выберите вариант ответа.";\n      feedback.className = "quiz-feedback incorrect";\n      feedback.hidden = false;\n      return;\n    }\n    const isCorrect = selected.value === "right";\n    feedback.textContent = (isCorrect ? "Верно. " : "Не совсем. ") + QUIZ_EXPLAIN[index];\n    feedback.className = `quiz-feedback ${isCorrect ? "correct" : "incorrect"}`;\n    feedback.hidden = false;\n    question.querySelectorAll("input").forEach((input) => { input.disabled = true; });\n    question.querySelector(\'input[value="right"]\').closest("label").classList.add("quiz-correct-answer");\n    button.disabled = true;\n    quizAnswered += 1;\n    quizScoreEl.textContent = `Отвечено: ${quizAnswered} / ${QUIZ_TOTAL}`;\n  });\n});\n'
